            _integer(row, "capacity", positive=True)
            for f in ("available_date", "valid_until"): _date(row, f)
            if row["status"] not in {"held", "available", "conditional", "unavailable"}:
                raise SourceError(f"row {row['_row']} has an unknown vendor status")
        elif name == "calendar":
            _required(row, ("constraint_id", "owner", "constraint_type", "start_at", "end_at", "priority", "notes", "record_version"))
            if row["priority"] not in {"hard", "soft"} or row["constraint_type"] not in {"preferred_event_window", "fallback_event_window", "venue_hold", "keynote_availability", "decision_deadline", "accessibility_walkthrough", "rehearsal_window", "teardown_deadline"}:
                raise SourceError(f"row {row['_row']} has an unknown calendar meaning")
            parsed = []
            for field in ("start_at", "end_at"):
                try: value = dt.datetime.fromisoformat(row[field])
                except ValueError as exc: raise SourceError(f"row {row['_row']} has an invalid timestamp") from exc
                if value.utcoffset() is None: raise SourceError(f"row {row['_row']} timestamp lacks an offset")
